import { handleTree, getId } from "@/utils/ruoyi.js"
import "@/styles/index.scss" // global css
import App from "./App.vue"
import store from "./store/index"
import router from "@/router/index.js"
import directives from "@/directives/index.js" // directive
import patterns from "@/patterns/index.js"
import formatters from "@/formatters/index.js"
import { getDicts } from "./utils/dict.js"
import VersionChecker from './utils/version-check.js'
const checker = new VersionChecker({
  interval: 1000, // 1 秒检测一次
})
checker.init()
import 'lazysizes'
import "./utils/imgPrfix.js"
import 'virtual:uno.css'
// 保存到全局，方便在动态创建的组件中使用
window.__VUE_APP_STORE__ = store
window.__VUE_APP_ROUTER__ = router
// 动态导入组件，按需加载
const components = import.meta.glob(
  [
    "./components/**/*.vue",
    "!./components/Process/*.vue",
    "!./components/ZsEditor/*.vue",
    "!./components/MenuTree/*.vue",
  ],
  {
    eager: false,
    import: "default",
  }
)
for (const [key, value] of Object.entries(components)) {
  const pathList = key.split("/")
  const name = pathList[pathList.length - 2]
  Vue.component(name, () => value())
}

if (store.state.app.platformConfig && store.state.app.platformConfig.buttonDefaultColor) {
  changeThemeColor(store.state.app.platformConfig.buttonDefaultColor)
}

store.watch(
  state => state.app.platformConfig.buttonDefaultColor,
  (newColor) => {
    if (newColor) {
      changeThemeColor(newColor)
    }
  }
)

import { POST, PUT, GET, DELETE, download } from "@/api"
import { setToken } from "./utils/auth.js"
// 全局方法挂载
Vue.prototype.getDicts = getDicts
Vue.prototype.handleTree = handleTree
Vue.prototype.patterns = patterns
Vue.prototype.formatters = formatters
// request方法
Vue.prototype.$post = POST
Vue.prototype.$put = PUT
Vue.prototype.$get = GET
Vue.prototype.$del = DELETE
Vue.prototype.download = download

// 消息提示
Vue.prototype.msgError = msgError
Vue.prototype.msgSuccess = msgSuccess
Vue.prototype.msgWarning = msgWarning

Vue.use(directives)

Vue.mixin({
  data() {
    return {
      bizStateOptions: store.state.common.bizStateOptions
    }
  },
  computed: {
    currentRoute: function () {
      return router.currentRoute.name.split("/")[0]
    },
    formMode: function () {
      return router.currentRoute.query.formMode
    },
  },
  methods: {
    getId,
    goBack() {
      const path =
        router.currentRoute.query.backUrl ||
        router.currentRoute.path.substring(0, router.currentRoute.path.lastIndexOf("/"))
      store.dispatch("tagsView/delView", router.currentRoute)
      router.push({ path, query: { type: "back" } })
    },
    // 改变表单页状态
    changeFormState(state, id = getId()) {
      store.dispatch("tagsView/delView", router.currentRoute)
      const path =
        state == "view"
          ? router.currentRoute.path.substring(
            0,
            router.currentRoute.path.lastIndexOf("/")
          ) +
          "/" +
          id
          : router.currentRoute.path
      router.push({ path, query: { ...router.currentRoute.query, formMode: state } })
    },
    dictFormatter(row, column, cellValue, index) {
      if (!cellValue) return ""
      const dictOptions = this[column.property + "Options"]
      if (!dictOptions || !Array.isArray(dictOptions)) return ""

      // 处理逗号分隔的多个值
      const values = String(cellValue).split(",")
      const labels = values.map(value => {
        const option = dictOptions.find(e => e.dictValue == value)
        return option?.dictLabel || value
      })

      return labels.join(", ")
    },
    checkPermission(value) {
      const all_permission = "*:*:*"
      const permissions = store.getters && store.getters.permissions
      if (value && value instanceof Array && value.length > 0) {
        const permissionFlag = value

        const hasPermissions = permissions.some((permission) => {
          return all_permission === permission || permissionFlag.includes(permission)
        })
        if (!hasPermissions) {
          console.warn(`请设置${value}权限标签`)
        }

        return hasPermissions
      }
      return true
    },
    isShowModify: function (key) {
      // 变更页面路由
      const arr = [
        "modify",
        "customerinfochange",
        "customerprojectchange",
        "buildingchange",
        "zzbg",
        "rybg",
        "projectchange",
        "planchange",
        "conlandlicchange",
        "landlicchange",
        "conslicchange",
        "conengplanlicchange",
        "mfcontractchange",
        "buildlandchange",
        "housingchange",
      ]
      if (!arr.includes(this.currentRoute)) {
        return false
      } else {
        if (!this.oldForm[key] && !this.form[key]) {
          return false
        }
        // 动态导入lodash.isequal
        return import('lodash.isequal').then(({ default: isEqual }) => {
          return !isEqual(this.oldForm[key], this.form[key])
            ? this.oldForm[key] || "空"
            : false
        })
      }
    },
  },
})

Vue.use(Element, {
  size: "mini",
})
let instance

function pickErrorMsgFromUrl(vm) {
  const fromSearch = new URLSearchParams(window.location.search).get("errorMsg")
  let fromRoute = vm.$route && vm.$route.query && vm.$route.query.errorMsg
  if (Array.isArray(fromRoute)) fromRoute = fromRoute[0]
  const raw = fromSearch != null && fromSearch !== "" ? fromSearch : fromRoute
  return raw != null && raw !== "" ? String(raw) : ""
}

function createInstance(params) {
  if (instance) return
  instance = new Vue({
    router,
    store,
    render: (h) => h(App),
  }).$mount("#app")
  instance.$nextTick(() => {
    const text = pickErrorMsgFromUrl(instance)
    if (text) {
      instance.$message.error(text)
    }
  })
}

const tokenFromUrl = new URLSearchParams(window.location.search).get("token")
if (tokenFromUrl) {
  setToken(tokenFromUrl)
  createInstance()
}
if (import.meta.env.VITE_APP_IS_IFRAME == "1") {
  let token = ""
  window.addEventListener(
    "message",
    (e) => {
      if (e.data.token) {
        token = e.data.token
        setToken(token)
        createInstance()
      }
      if (e.data.router) {
        sessionStorage.setItem("routers", JSON.stringify(e.data.router))
      }
      if (e.data.outLink == 1) {
        store.dispatch("app/setOutLink", e.data.outLink)
      }
    },
    false
  )
} else if (!tokenFromUrl) {
  createInstance()
}

Vue.config.productionTip = false

export default instance"}]

